// On-device wayfinding: a 1:1 port of vision/navigation/graph.py (route) and vision/navigation/places.py
// (resolve, parseRequest, directions). Offline answers therefore match the server's. Parity is checked by
// test/router_parity_test.dart against fixtures generated by the Python implementation.
import 'dart:math' as math;

import 'models.dart';

class RouteError implements Exception {
  RouteError(this.message);
  final String message;
  @override
  String toString() => message;
}

String norm(String s) => s.toLowerCase().replaceAll(RegExp(r'[^a-z0-9]'), '');

/// Python's round(): half to even.
int pyRound(double x) {
  final f = x.floorToDouble();
  final diff = x - f;
  if (diff > 0.5) return f.toInt() + 1;
  if (diff < 0.5) return f.toInt();
  return f.toInt().isEven ? f.toInt() : f.toInt() + 1;
}

/// Python's f"{x:.1f}" (round half to even on the decimal value).
String pyFixed1(double x) {
  final scaled = x * 10;
  final r = pyRound(double.parse(scaled.toStringAsFixed(6)));
  final s = (r / 10).toStringAsFixed(1);
  return s == '-0.0' ? '0.0' : s;
}

double roundTo(double x, int digits) {
  final m = math.pow(10, digits).toDouble();
  return pyRound(x * m) / m;
}

class _HeapItem {
  _HeapItem(this.d, this.id);
  final double d;
  final String id;
  int compareTo(_HeapItem o) => d != o.d ? d.compareTo(o.d) : id.compareTo(o.id);
}

class _MinHeap {
  final List<_HeapItem> _a = [];
  bool get isEmpty => _a.isEmpty;
  void push(_HeapItem x) {
    _a.add(x);
    var i = _a.length - 1;
    while (i > 0) {
      final p = (i - 1) >> 1;
      if (_a[p].compareTo(_a[i]) <= 0) break;
      final t = _a[p];
      _a[p] = _a[i];
      _a[i] = t;
      i = p;
    }
  }

  _HeapItem pop() {
    final top = _a.first;
    final last = _a.removeLast();
    if (_a.isNotEmpty) {
      _a[0] = last;
      var i = 0;
      while (true) {
        final l = 2 * i + 1, r = l + 1;
        var m = i;
        if (l < _a.length && _a[l].compareTo(_a[m]) < 0) m = l;
        if (r < _a.length && _a[r].compareTo(_a[m]) < 0) m = r;
        if (m == i) break;
        final t = _a[m];
        _a[m] = _a[i];
        _a[i] = t;
        i = m;
      }
    }
    return top;
  }
}

class Wayfinder {
  Wayfinder(this.pack) {
    for (final n in pack.nodes) {
      nodes[n.id] = n;
    }
    for (final e in pack.edges) {
      edgeMap['${e.a}\u0001${e.b}'] = e;
      edgeMap['${e.b}\u0001${e.a}'] = e;
    }
  }

  final MapPack pack;
  final Map<String, GNode> nodes = {};
  final Map<String, GEdge> edgeMap = {};

  Set<String> get classes => {for (final n in pack.nodes) if (n.className != null) n.className!};

  // ------------------------------------------------------------------ resolve / parse
  String resolve(String ref) {
    if (nodes.containsKey(ref)) return ref;
    if (pack.isBuilding) return resolveAll(ref).first;
    final key = norm(ref);
    if (const ['start', 'videostart', 'entrance0', 'begin'].contains(key)) {
      return pack.defaultStart?.id ?? 'cam0';
    }
    for (final p in pack.places) {
      if (key == norm(p.name) || p.aliases.map(norm).contains(key)) return p.id;
    }
    final cls = classes;
    if (cls.contains(ref)) return ref;
    for (final e in pack.classWords.entries) {
      if (cls.contains(e.key) && e.value.map(norm).contains(key)) return e.key;
    }
    throw RouteError("no place or facility called '$ref' in this map");
  }

  /// Free text -> (start ref or null, goal ref, display names).
  ({String? start, String goal, String? startName, String goalName}) parseRequest(String text) {
    final t = ' ${text.toLowerCase()} ';
    final tn = norm(text);
    final names = <(String, String, String)>[];
    for (final p in pack.places) {
      for (final nm in [p.name, ...p.aliases]) {
        names.add((norm(nm), p.id, p.name));
      }
    }
    final cls = classes;
    for (final e in pack.classWords.entries) {
      if (cls.contains(e.key)) {
        for (final w in e.value) {
          names.add((norm(w), e.key, e.key.replaceAll('_', ' ')));
        }
      }
    }
    // stable sort by descending needle length (Python sorted is stable)
    final indexed = names.asMap().entries.toList()
      ..sort((a, b) {
        final c = b.value.$1.length.compareTo(a.value.$1.length);
        return c != 0 ? c : a.key.compareTo(b.key);
      });
    final hits = <(int, String, String, String)>[];
    for (final it in indexed) {
      final (needle, ref, disp) = it.value;
      if (needle.isEmpty) continue;
      final i = tn.indexOf(needle);
      if (i >= 0 && !hits.any((h) => i < h.$1 + h.$2.length && h.$1 < i + needle.length)) {
        hits.add((i, needle, ref, disp));
      }
    }
    hits.sort((a, b) {
      for (final c in [a.$1.compareTo(b.$1), a.$2.compareTo(b.$2), a.$3.compareTo(b.$3), a.$4.compareTo(b.$4)]) {
        if (c != 0) return c;
      }
      return 0;
    });
    if (hits.isEmpty) {
      final names = pack.places.map((p) => p.name).join(', ');
      throw RouteError(
          'I could not find a known place in that request. Tagged places: ${names.isEmpty ? 'none yet' : names}');
    }
    final fromIdx = [t.indexOf(' from '), t.indexOf(' i am at '), t.indexOf(" i'm at "), t.indexOf(' im at ')]
        .reduce(math.max);
    if (hits.length >= 2 && fromIdx >= 0) {
      return (start: hits.first.$3, goal: hits.last.$3, startName: hits.first.$4, goalName: hits.last.$4);
    }
    return (start: null, goal: hits.last.$3, startName: null, goalName: hits.last.$4);
  }

  // ------------------------------------------------------------------ routing (graph.py)
  double _cost(GEdge e, Map<String, dynamic> prof) {
    var m = 1.0;
    for (final t in e.tags) {
      if (prof.containsKey(t) && t != 'label') {
        final v = prof[t];
        m = v == null ? double.infinity : math.max(m, (v as num).toDouble());
      }
    }
    return e.length * m;
  }

  RouteResult route(String start, String goal, {String profile = 'standard'}) {
    final raw = _rawRoute(start, goal, profile);
    if (!raw.feasible) return raw;
    return pack.isBuilding ? _buildingDirections(raw) : _directions(raw);
  }

  RouteResult _rawRoute(String start, String goal, String profile) {
    final profiles = pack.profiles;
    if (!profiles.containsKey(profile)) throw RouteError('profile must be one of ${profiles.keys.toList()}');
    final prof = profiles[profile]!;
    Set<String> targets;
    if (!nodes.containsKey(goal)) {
      targets = {for (final n in pack.nodes) if (n.className == goal) n.id};
      if (targets.isEmpty) throw RouteError("no registered '$goal' on this map");
    } else {
      targets = {goal};
    }
    if (!nodes.containsKey(start)) throw RouteError('unknown start $start');
    final adj = <String, List<(String, double, GEdge)>>{};
    for (final e in pack.edges) {
      final c = _cost(e, prof);
      adj.putIfAbsent(e.a, () => []).add((e.b, c, e));
      adj.putIfAbsent(e.b, () => []).add((e.a, c, e));
    }
    final dist = <String, double>{start: 0};
    final prev = <String, (String, GEdge)>{};
    final pq = _MinHeap()..push(_HeapItem(0, start));
    String? reached;
    while (!pq.isEmpty) {
      final it = pq.pop();
      if (it.d > (dist[it.id] ?? double.infinity)) continue;
      if (targets.contains(it.id)) {
        reached = it.id;
        break;
      }
      for (final (v, c, e) in adj[it.id] ?? const <(String, double, GEdge)>[]) {
        if (!c.isFinite) continue;
        final nd = it.d + c;
        if (nd < (dist[v] ?? double.infinity)) {
          dist[v] = nd;
          prev[v] = (it.id, e);
          pq.push(_HeapItem(nd, v));
        }
      }
    }
    if (reached == null) {
      final alt = profile != 'standard' ? _rawRoute(start, goal, 'standard') : null;
      return RouteResult(
        feasible: false,
        profile: profile,
        reason: "no route satisfying '${prof['label']}' within this reconstruction"
            '${alt != null && alt.feasible ? ' (a route exists only via stairs)' : ''}',
      );
    }
    final path = <String>[reached];
    final segs = <GEdge>[];
    while (path.last != start) {
      final (u, e) = prev[path.last]!;
      segs.add(e);
      path.add(u);
    }
    final ids = path.reversed.toList();
    final segList = segs.reversed.toList();
    final length = segList.fold<double>(0, (s, e) => s + e.length);
    final warnings = <String>{
      for (final e in segList)
        for (final t in e.tags)
          if (const ['stairs', 'stairs_no_handrail', 'obstacle'].contains(t)) t
    }.toList()
      ..sort();
    final units = pack.scaleStatus != 'relative' ? 'm' : 'units';
    return RouteResult(
      feasible: true,
      profile: profile,
      profileLabel: prof['label'] as String?,
      goal: reached,
      path: [for (final i in ids) nodes[i]!.pos],
      nodes: ids,
      length: roundTo(length, 3),
      units: units,
      warnings: warnings,
    );
  }

  // ------------------------------------------------------------------ buildings (building.py)
  static final _floorRe = RegExp(
      r'\b(?:on|at)?\s*(?:the\s+)?(?:(ground)|(\d+)(?:st|nd|rd|th)?|(first|second|third|fourth|fifth))\s+(?:floor|level)\b|\b(?:floor|level)\s+(\d+)\b',
      caseSensitive: false);
  static const _wordLevel = {'ground': 0, 'first': 1, 'second': 2, 'third': 3, 'fourth': 4, 'fifth': 5};
  static const _ordinals = ['Ground', 'First', 'Second', 'Third', 'Fourth', 'Fifth', 'Sixth', 'Seventh', 'Eighth', 'Ninth'];

  static String floorLabel(int level) =>
      level < 0 ? 'Basement ${-level}' : (level < _ordinals.length ? '${_ordinals[level]} floor' : 'Floor $level');

  static String _strip(String s, String chars) {
    var a = 0, b = s.length;
    while (a < b && chars.contains(s[a])) {
      a++;
    }
    while (b > a && chars.contains(s[b - 1])) {
      b--;
    }
    return s.substring(a, b);
  }

  /// "CG Lab on the 2nd floor" -> ("CG Lab", 2)
  static (String, int?) splitFloor(String text) {
    final m = _floorRe.firstMatch(text);
    if (m == null) return (text, null);
    final num = m.group(2) ?? m.group(4);
    final lv = m.group(1) != null ? 0 : (num != null ? int.parse(num) : _wordLevel[m.group(3)!.toLowerCase()]!);
    return (_strip(text.substring(0, m.start) + text.substring(m.end), ' ,-()'), lv);
  }

  /// Every node a reference can mean in a building (a name can exist on several floors: the router then picks
  /// the nearest one).
  List<String> resolveAll(String ref) {
    if (nodes.containsKey(ref)) return [ref];
    if (const ['start', 'entrance0', 'begin', 'groundentrance'].contains(norm(ref))) return [pack.startId!];
    final full = norm(ref);
    final exact = pack.places.where((p) => full == norm(p.name) || p.aliases.map(norm).contains(full)).toList();
    if (exact.isNotEmpty) return [for (final p in exact) p.id]; // an exact place name wins ("Third floor corridor")
    final (name, lv) = splitFloor(ref);
    final key = norm(name);
    var hits = pack.places.where((p) => key == norm(p.name) || p.aliases.map(norm).contains(key)).toList();
    if (lv != null) hits = hits.where((p) => p.floor == lv).toList();
    if (hits.isNotEmpty) return [for (final p in hits) p.id];
    final cls = classes;
    for (final e in pack.classWords.entries) {
      if (cls.contains(e.key) && (key == norm(e.key) || e.value.map(norm).contains(key))) {
        return [for (final n in pack.nodes) if (n.className == e.key && (lv == null || n.floor == lv)) n.id];
      }
    }
    throw RouteError("no place called '$ref' in this building");
  }

  /// Route across floors to the nearest match of [goal] (like POST /buildings/{id}/route).
  RouteResult routeBuilding(String? start, String goal, {String profile = 'standard'}) {
    final s = start == null ? pack.startId! : resolveAll(start).first;
    RouteResult? best;
    for (final c in resolveAll(goal)) {
      final r = _rawRoute(s, c, profile);
      if (r.feasible && (best == null || r.length! < best.length!)) best = r;
    }
    if (best == null) {
      final r = _rawRoute(s, resolveAll(goal).first, profile);
      var why = (r.reason ?? 'no route').replaceAll('within this reconstruction', 'in this building');
      final down = [
        for (final c in (pack.raw['connectors'] as List? ?? const []))
          if ((c as Map)['out_of_service'] == true) c['name'] as String
      ];
      if (down.isNotEmpty) why += ' (${down.join(', ')} out of service)';
      return RouteResult(feasible: false, profile: profile, reason: why);
    }
    return _buildingDirections(best);
  }

  RouteResult _buildingDirections(RouteResult rt) {
    final ids = rt.nodes;
    final segs = <List<String>>[];
    var cur = <String>[ids.first];
    final rides = <({String connector, String name, String kind, String from, String to})>[];
    for (var k = 0; k < ids.length - 1; k++) {
      final a = ids[k], b = ids[k + 1];
      final e = edgeMap['$a\u0001$b']!;
      if (e.tags.contains('connector')) {
        if (rides.isNotEmpty && rides.last.connector == e.connector && rides.last.to == a && cur.length == 1 && cur.first == a) {
          final r = rides.removeLast();
          rides.add((connector: r.connector, name: r.name, kind: r.kind, from: r.from, to: b));
        } else {
          segs.add(cur);
          rides.add((connector: e.connector!, name: e.connectorName!, kind: e.connectorKind!, from: a, to: b));
        }
        cur = [b];
      } else {
        cur.add(b);
      }
    }
    segs.add(cur);
    final prof = pack.help[rt.profile] ?? pack.help['standard']!;
    final names = {for (final f in pack.floors) f.level: f.name};
    final out = <DirectionStep>[];
    for (var i = 0; i < segs.length; i++) {
      final seg = segs[i];
      final lv = nodes[seg.first]!.floor;
      var d = <DirectionStep>[];
      if (seg.length > 1) {
        var len = 0.0;
        for (var k = 0; k < seg.length - 1; k++) {
          len += edgeMap['${seg[k]}\u0001${seg[k + 1]}']!.length;
        }
        final sub = RouteResult(
            feasible: true, profile: rt.profile, nodes: seg, units: rt.units, length: len, path: [for (final x in seg) nodes[x]!.pos]);
        d = _directions(sub).directions;
        if (i > 0) d = d.where((x) => x.kind != 'start').toList();
        if (i < segs.length - 1) d = d.where((x) => x.kind != 'arrive').toList();
      } else if (i == 0) {
        d = [
          DirectionStep('start', 'Start at ${nodes[seg.first]!.name ?? 'your position'}. ${prof['intro'] ?? ''}'.trim(), at: seg.first)
        ];
      }
      if (i == segs.length - 1 && seg.length == 1) {
        d.add(DirectionStep('arrive', 'You have arrived at ${nodes[seg.first]!.name ?? 'your destination'}.', at: seg.first));
      }
      out.addAll(d.map((x) => x.withFloor(lv)));
      if (i < rides.length) {
        final r = rides[i];
        final la = nodes[r.from]!.floor!, lb = nodes[r.to]!.floor!;
        final n = (lb - la).abs();
        final way = lb > la ? 'up' : 'down';
        final span = n > 1 ? ' ($n floors)' : '';
        final txt = 'Take ${r.name} $way to the ${names[lb] ?? floorLabel(lb)}$span.';
        final stairsHelp = prof['stairs'];
        final notes = r.kind == 'lift'
            ? (rt.profile == 'wheelchair' ? ['Step-free: lift.'] : <String>[])
            : (stairsHelp != null && stairsHelp.isNotEmpty ? [stairsHelp] : <String>[]);
        out.add(DirectionStep(r.kind == 'lift' ? 'lift' : 'stairs', txt, notes: notes, at: r.from, to: r.to, floor: la, toFloor: lb));
      }
    }
    final sn = nodes[ids.first]!, gn = nodes[ids.last]!;
    return RouteResult(
      feasible: true,
      profile: rt.profile,
      profileLabel: rt.profileLabel,
      goal: rt.goal,
      path: rt.path,
      nodes: ids,
      length: rt.length,
      units: rt.units,
      warnings: rt.warnings,
      directions: out,
      startName: sn.name ?? 'your position',
      goalName: gn.name ?? (gn.className ?? 'destination').replaceAll('_', ' '),
      floors: [...{for (final seg in segs) nodes[seg.first]!.floor!}],
      pathFloors: [for (final x in ids) nodes[x]!.floor!],
    );
  }

  // ------------------------------------------------------------------ directions (places.py)
  static double _crossV(List<double> a, List<double> b) => a[0] * b[1] - a[1] * b[0];
  static double _angleDeg(List<double> a, List<double> b) =>
      math.atan2(_crossV(a, b), a[0] * b[0] + a[1] * b[1]) * 180 / math.pi;
  static List<double> _ground(List<double> v) => [v[0], v[2]];
  static List<double> _sub(List<double> a, List<double> b) => [for (var i = 0; i < a.length; i++) a[i] - b[i]];
  static double _len(List<double> v) => math.sqrt(v.fold<double>(0, (s, x) => s + x * x));

  static String _distText(double d, String unit, double total) {
    if (unit == 'm') {
      if (d < 1.5) return 'a few steps';
      return d >= 3 ? 'about ${pyRound(d)} m' : 'about ${pyFixed1(d)} m';
    }
    final frac = total != 0 ? d / total : 0;
    return frac < 0.15 ? 'a short way' : (frac < 0.45 ? 'part of the way' : 'most of the way');
  }

  static const _defaultNotes = {
    'stairs': 'Stairs on this stretch.',
    'ramp': 'Ramp on this stretch.',
    'obstacle': 'Obstacle reported near the path.',
    'stairs_no_handrail': 'Stairs with no handrail found.',
  };

  RouteResult _directions(RouteResult rt) {
    final ids = rt.nodes;
    final unit = rt.units!;
    final total = (rt.length ?? 0) == 0 ? 1e-9 : rt.length!;
    final help = pack.help;
    final prof = help[rt.profile] ?? help['standard']!;
    final pts = [for (final i in ids) nodes[i]!.pos];
    final med = pack.medianStep == 0 ? 1e-6 : pack.medianStep;
    final near = pack.nearClasses;
    final landmarks = pack.nodes
        .where((n) =>
            n.id != ids.first &&
            n.id != ids.last &&
            ((n.kind == 'facility' && near.contains(n.className)) || n.kind == 'place'))
        .toList();
    final used = <String>{};
    final out = <DirectionStep>[];
    final startName = nodes[ids.first]!.name ?? (ids.first == 'cam0' ? 'the start of the walk' : 'your position');
    final goal = nodes[ids.last]!;
    final goalName = goal.name ?? 'the ${(goal.className ?? 'destination').replaceAll('_', ' ')}';
    out.add(DirectionStep('start', 'Start at $startName. ${prof['intro'] ?? ''}'.trim(), at: ids.first));

    List<double>? segDir;
    var runLen = 0.0;
    var runStart = 0;
    var runTags = <String>{};
    final legs = <({int from, int to, List<double> dir, double length, Set<String> tags, double? turn})>[];
    for (var k = 0; k < ids.length - 1; k++) {
      final a = pts[k], b = pts[k + 1];
      var d = _ground(_sub(b, a));
      final L = _len(_sub(b, a));
      final e = edgeMap['${ids[k]}\u0001${ids[k + 1]}'];
      final tags = e?.tags ?? const <String>[];
      if (_len(d) < 1e-9 || tags.contains('approach')) {
        runLen += L;
        runTags.addAll(tags);
        continue;
      }
      final dn = _len(d);
      d = [d[0] / dn, d[1] / dn];
      if (segDir != null && _angleDeg(segDir, d).abs() > 35 && runLen > 0.3 * med) {
        legs.add((from: runStart, to: k, dir: segDir, length: runLen, tags: runTags, turn: _angleDeg(segDir, d)));
        runLen = 0;
        runStart = k;
        runTags = <String>{};
        segDir = d;
      } else if (segDir == null) {
        segDir = d;
      } else {
        final s = [segDir[0] * runLen + d[0] * L, segDir[1] * runLen + d[1] * L];
        final sl = _len(s);
        segDir = sl == 0 ? s : [s[0] / sl, s[1] / sl];
      }
      runLen += L;
      runTags.addAll(tags);
    }
    legs.add((from: runStart, to: ids.length - 1, dir: segDir ?? [1.0, 0.0], length: runLen, tags: runTags, turn: null));

    for (final leg in legs) {
      var txt = 'Go straight for ${_distText(leg.length, unit, total)}';
      final notes = <String>[];
      for (final tag in const ['stairs_no_handrail', 'stairs', 'ramp', 'obstacle']) {
        if (leg.tags.contains(tag)) {
          if (tag == 'stairs' && leg.tags.contains('stairs_no_handrail')) continue;
          final p = prof[tag];
          notes.add((p != null && p.isNotEmpty) ? p : _defaultNotes[tag]!);
        }
      }
      final seen = <String>[];
      for (var k = leg.from; k <= leg.to; k++) {
        for (final lm in landmarks) {
          if (used.contains(lm.id)) continue;
          final v = _sub(lm.pos, pts[k]);
          if (_len(v) < 1.5 * med) {
            final side = _crossV(leg.dir, _ground(v));
            final where = side > 0.15 * med ? ' on your right' : (side < -0.15 * med ? ' on your left' : '');
            final nm = lm.name ?? 'the ${(lm.className ?? '').replaceAll('_', ' ')}';
            seen.add('$nm$where');
            used.add(lm.id);
            final door = prof['door'];
            if (lm.className == 'door' && door != null && door.isNotEmpty) notes.add(door);
          }
        }
      }
      if (seen.isNotEmpty) txt += ', passing ${seen.take(3).join(', ')}';
      out.add(DirectionStep('walk', '$txt.',
          length: roundTo(leg.length, 3), notes: notes, at: ids[leg.from], to: ids[leg.to]));
      final a = leg.turn;
      if (a != null) {
        final word = a.abs() > 140
            ? 'Turn around'
            : (a.abs() > 60 ? (a > 0 ? 'Turn right' : 'Turn left') : (a > 0 ? 'Bear right' : 'Bear left'));
        out.add(DirectionStep('turn', '$word.', angle: pyRound(a), at: ids[leg.to]));
      }
    }
    final extra = <String>[];
    final gp = pack.places.where((p) => p.id == goal.id).firstOrNull;
    if (gp != null) {
      if ((gp.description ?? '').isNotEmpty) extra.add(gp.description!);
      if (gp.stepFree == false && rt.profile == 'wheelchair') extra.add('Note: this place is marked as NOT step-free.');
      if ((gp.accessNotes ?? '').isNotEmpty) extra.add(gp.accessNotes!);
    }
    final arriveHelp = prof['arrive'];
    if (arriveHelp != null && arriveHelp.isNotEmpty) extra.add(arriveHelp);
    final cleaned = [
      for (final x in extra)
        if (x.trim().isNotEmpty)
          (x.trimRight().endsWith('.') || x.trimRight().endsWith('!') || x.trimRight().endsWith('?'))
              ? x
              : '${x.trimRight()}.'
    ];
    out.add(DirectionStep('arrive', ['You have arrived at $goalName.', ...cleaned].join(' ').trim(), at: ids.last));
    return RouteResult(
      feasible: true,
      profile: rt.profile,
      profileLabel: rt.profileLabel,
      goal: rt.goal,
      path: rt.path,
      nodes: rt.nodes,
      length: rt.length,
      units: rt.units,
      warnings: rt.warnings,
      directions: out,
      startName: startName,
      goalName: goalName,
    );
  }

  /// Full free-text request handling, like POST /navigation/{id}/ask.
  ({RouteResult route, String start, String goalName}) ask(String text, {String profile = 'standard', String? start}) {
    final q = parseRequest(text);
    if (pack.isBuilding) {
      final st = q.start != null ? resolveAll(q.start!).first : (start != null ? resolveAll(start).first : pack.startId!);
      return (route: routeBuilding(st, q.goal, profile: profile), start: st, goalName: q.goalName);
    }
    final st = resolve(q.start ?? start ?? 'start');
    return (route: route(st, q.goal, profile: profile), start: st, goalName: q.goalName);
  }
}
